<script setup lang="ts">
import { ref, computed, onMounted, onUnmounted } from 'vue'
import { request, idempotencyKey } from '../../lib/api'
import { money, photo, orderStatus, type ShopProduct } from '../../lib/shop'
import ShopProductCard from '../../components/ShopProduct.vue'
import AdPlacement from '../../components/AdPlacement.vue'

const nav=[{id:'home',label:'商城首页',short:'首页',icon:'⌂'},{id:'category',label:'商品分类',short:'分类',icon:'▦'},{id:'points',label:'积分商城',short:'积分',icon:'◇'},{id:'cart',label:'购物车',short:'购物车',icon:'▱'},{id:'mine',label:'我的商城',short:'我的',icon:'♙'}]
const active=ref('home'),catalog=ref<ShopProduct[]>([]),user=ref<any>(null),cart=ref<any[]>([]),addresses=ref<any[]>([]),orders=ref<any[]>([]),coupons=ref<any[]>([]),ledger=ref<any[]>([])
const loading=ref(true),error=ref(''),busy=ref(false),message=ref(''),query=ref(''),category=ref('全部'),sort=ref('综合'),modal=ref(''),consent=ref(false),selected=ref<ShopProduct|null>(null)
const checkoutItems=ref<any[]>([]),addressId=ref(''),couponId=ref(''),checkoutKey=ref(''),payOrder=ref<any>(null),orderFilter=ref('全部'),infoTitle=ref(''),infoBody=ref('')
const recipient=ref(''),phone=ref(''),detail=ref(''),adsEnabled=ref(true),placements=ref<any[]>([]),ad=ref<any>(null),seconds=ref(0)
const favorites=ref<string[]>(uni.getStorageSync('aurora-favorites')||[])
let noticeTimer:ReturnType<typeof setTimeout>|undefined,adTimer:ReturnType<typeof setInterval>|undefined
const categories=['全部','数码好物','生活美学','出行装备']
const shopProducts=computed(()=>catalog.value.filter(p=>p.price>0))
const shown=computed(()=>{
 let list=(active.value==='points'?catalog.value:shopProducts.value).filter(p=>(category.value==='全部'||p.category===category.value)&&(!query.value||p.name.includes(query.value)||p.category.includes(query.value)))
 if(sort.value==='价格升序')list=[...list].sort((a,b)=>a.price-b.price)
 if(sort.value==='返积分优先')list=[...list].sort((a,b)=>b.rewardPoints-a.rewardPoints)
 if(sort.value==='低积分优先')list=[...list].sort((a,b)=>a.points-b.points)
 return list
})
const cartCount=computed(()=>cart.value.reduce((n,p)=>n+p.quantity,0))
const cartTotal=computed(()=>cart.value.reduce((n,p)=>n+p.price*p.quantity,0))
const subtotal=computed(()=>checkoutItems.value.reduce((n,p)=>n+p.price*p.quantity,0))
const discount=computed(()=>coupons.value.find(c=>c.id===couponId.value)?.discount||0)
const payable=computed(()=>Math.max(0,subtotal.value-discount.value))
const selectedAddress=computed(()=>addresses.value.find(a=>a.id===addressId.value))
const availableCoupons=computed(()=>coupons.value.filter(c=>c.status==='available'&&subtotal.value>=c.threshold))
const visibleOrders=computed(()=>orders.value.filter(o=>orderFilter.value==='全部'||orderStatus[o.status]===orderFilter.value))
const pointBalance=computed(()=>Number(user.value?.points||0).toLocaleString())
function tell(s:string){message.value=s;if(noticeTimer)clearTimeout(noticeTimer);noticeTimer=setTimeout(()=>message.value='',3500)}
async function act(fn:()=>Promise<void>){if(busy.value)return;busy.value=true;try{await fn()}catch(e:any){tell(e.message)}finally{busy.value=false}}
function info(title:string,body:string){infoTitle.value=title;infoBody.value=body;modal.value='info'}
function go(id:string){active.value=id;query.value='';category.value='全部';sort.value='综合';uni.pageScrollTo({scrollTop:0,duration:120});if(id==='checkout'&&!checkoutItems.value.length)active.value='cart'}
function logged(){if(user.value)return true;modal.value='login';return false}
async function refresh(){
 const c=await request('/catalog');catalog.value=c.products;placements.value=c.placements;adsEnabled.value=c.adsEnabled
 if(uni.getStorageSync('aurora-token')){
  try{
   user.value=await request('/me')
   const [ca,ad,or,co,le]=await Promise.all([request('/cart'),request('/addresses'),request('/shop/orders'),request('/coupons'),request('/ledger')])
   cart.value=ca.items;addresses.value=ad.items;orders.value=or.items;coupons.value=co.items;ledger.value=le.items
   if(!addresses.value.some(a=>a.id===addressId.value))addressId.value=addresses.value[0]?.id||''
  }catch(e:any){if(e.status===401){user.value=null;cart.value=[];orders.value=[];ledger.value=[];addresses.value=[];coupons.value=[]}else throw e}
 }
}
async function load(){loading.value=true;error.value='';try{await refresh()}catch(e:any){error.value=e.message}finally{loading.value=false}}
async function login(){if(!consent.value){tell('请先阅读并同意体验与隐私说明');return}await act(async()=>{const r=await request('/auth/demo','POST',{consent:true});uni.setStorageSync('aurora-token',r.token);modal.value='';await refresh();tell('登录成功，购物确认收货后可得积分')})}
async function logout(){await act(async()=>{await request('/auth/logout','POST',{});uni.removeStorageSync('aurora-token');user.value=null;cart.value=[];orders.value=[];addresses.value=[];coupons.value=[];ledger.value=[];go('home');tell('已退出登录')})}
function openProduct(p:ShopProduct){selected.value=p;modal.value='product'}
async function addCart(p:ShopProduct){if(!logged())return;await act(async()=>{const quantity=(cart.value.find(c=>c.id===p.id)?.quantity||0)+1;await request('/cart','POST',{productId:p.id,quantity});modal.value='';await refresh();tell('已加入购物车')})}
async function changeQty(p:any,delta:number){if(p.quantity+delta<1)return;await act(async()=>{await request('/cart','POST',{productId:p.id,quantity:p.quantity+delta});await refresh()})}
async function removeCart(p:any){await act(async()=>{await request('/cart/remove','POST',{productId:p.id});await refresh()})}
function openCheckout(items:any[]){if(!logged())return;if(!items.length){tell('先挑选一件喜欢的商品吧');return}checkoutItems.value=items.map(p=>({...p,quantity:p.quantity||1}));couponId.value='';checkoutKey.value=idempotencyKey();modal.value='';active.value='checkout';uni.pageScrollTo({scrollTop:0,duration:100})}
async function submitOrder(){if(!selectedAddress.value){modal.value='addresses';return}await act(async()=>{
 const r=await request('/shop/checkout','POST',{items:checkoutItems.value.map(p=>({productId:p.id,quantity:p.quantity})),addressId:addressId.value,couponId:couponId.value,requestKey:checkoutKey.value});payOrder.value=r.order;checkoutItems.value=[];await refresh();active.value='orders';orderFilter.value='待付款';modal.value='pay'
})}
async function pay(){if(!payOrder.value)return;await act(async()=>{await request(`/shop/orders/${payOrder.value.id}/demo-pay`,'POST',{});modal.value='';orderFilter.value='待发货';await refresh();tell('测试付款完成，未实际扣款；积分待确认收货后入账')})}
async function orderAction(o:any,action:string){await act(async()=>{await request(`/shop/orders/${o.id}/${action}`,'POST',{});await refresh();orderFilter.value='全部';tell(action==='receive'?`确认收货成功，${o.reward} 积分已到账`:action==='demo-ship'?'模拟发货完成，没有真实物流':action==='cancel'?'订单已取消，库存已释放':'测试退款完成，订单与积分已同步处理')})}
async function saveAddress(){await act(async()=>{const r=await request('/addresses','POST',{recipient:recipient.value,phone:phone.value,detail:detail.value});await refresh();addressId.value=r.id;recipient.value='';phone.value='';detail.value='';modal.value='addresses';tell('地址已保存')})}
async function removeAddress(id:string){await act(async()=>{await request('/addresses/remove','POST',{id});await refresh()})}
async function redeem(){if(!selected.value||!logged())return;await act(async()=>{await request('/orders','POST',{productId:selected.value!.id,requestKey:checkoutKey.value||idempotencyKey()});checkoutKey.value='';modal.value='';await refresh();tell(selected.value?.id==='coupon'?'兑换成功，购物券已放入我的优惠券':'积分兑换已记录；当前不真实发货')})}
function redeemProduct(p:ShopProduct){selected.value=p;checkoutKey.value=idempotencyKey();modal.value='redeem'}
async function checkin(){if(!logged())return;await act(async()=>{const r=await request('/checkin','POST',{});await refresh();tell(`签到成功，获得 ${r.reward} 积分`)})}
async function startAd(){if(!logged())return;await act(async()=>{ad.value=await request('/ads/start','POST',{});seconds.value=ad.value.minimumSeconds;modal.value='ad';if(adTimer)clearInterval(adTimer);const end=Date.now()+seconds.value*1000;adTimer=setInterval(()=>{seconds.value=Math.max(0,Math.ceil((end-Date.now())/1000));if(!seconds.value&&adTimer)clearInterval(adTimer)},250)})}
async function claimAd(){if(seconds.value)return;await act(async()=>{await request('/ads/claim','POST',{sessionId:ad.value.id});modal.value='';await refresh();tell('30 演示积分已到账')})}
function close(){modal.value='';if(adTimer)clearInterval(adTimer)}
function favorite(p:ShopProduct){favorites.value=favorites.value.includes(p.id)?favorites.value.filter(id=>id!==p.id):[...favorites.value,p.id];uni.setStorageSync('aurora-favorites',favorites.value);tell(favorites.value.includes(p.id)?'已收藏':'已取消收藏')}
function showOrders(filter='全部'){if(!logged())return;orderFilter.value=filter;go('orders')}
function rules(){info('购物积分规则','购物按优惠后实付金额，每满 1 元奖励 1 积分，不足 1 元不计。付款后积分待入账，确认收货后到账；取消订单不发积分，退款回收已发放积分。已使用返还积分导致余额不足时，需人工售后审核。签到和广告仅为补充任务。积分不出售、不提现、不转让，不参与随机抽奖。当前全部为测试交易，不扣款、不发货。')}
function privacy(){info('隐私与体验说明','本测试版保存随机账户、登录会话、地址、购物车、订单、积分、优惠券和安全操作记录。请只填写虚构的收货信息，不输入真实隐私。心愿单保存在本设备。未接入支付、物流、广告或数美 SDK，不向这些平台发送数据。正式运营前需补充运营主体、数据保留与删除、注销和申诉等完整政策。')}
function admin(){uni.navigateTo({url:'/pages/admin/index'})}
const date=(n:number)=>new Date(n).toLocaleString('zh-CN',{hour12:false})
onMounted(load)
onUnmounted(()=>{if(noticeTimer)clearTimeout(noticeTimer);if(adTimer)clearInterval(adTimer)})
</script>

<template>
 <view class="mall">
  <view class="m-topline"><view class="m-width"><text>好物认真选 · 购物有积分</text><view><text class="m-test-badge">测试商城 · 不真实扣款</text><text @click="rules">积分规则</text><text @click="admin">商家后台 ↗</text></view></view></view>
  <view class="m-header"><view class="m-width m-header-inner"><view class="m-brand" @click="go('home')"><text class="m-brand-symbol">曜</text><view><text class="m-brand-title">曜集商城</text><text class="m-brand-sub">买好物 · 得积分 · 兑好礼</text></view></view><view class="m-search"><text>⌕</text><input v-model="query" placeholder="搜好物，看看能得多少积分" @confirm="active='category'"/><button role="button" @click="active='category'">搜索</button></view><view class="m-header-account" @click="user?go('mine'):modal='login'"><text class="m-account-icon">♙</text><view><text>{{user?'我的账户':'登录 / 注册'}}</text><text class="m-muted">{{user?`${pointBalance} 可用积分`:'开启购物积分体验'}}</text></view></view><view class="m-header-cart" @click="go('cart')">▱<text>购物车</text><text class="m-cart-badge">{{cartCount}}</text></view></view></view>
  <view class="m-desktop-nav"><view class="m-width"><view v-for="n in nav" :key="n.id" :class="{on:active===n.id}" @click="go(n.id)">{{n.label}}</view><view :class="{on:active==='tasks'}" @click="go('tasks')">签到领积分</view><text class="m-nav-tip">购物返积分，确认收货后到账</text></view></view>
  <view class="m-width m-main">
   <view v-if="loading" class="m-empty"><text class="m-empty-symbol">◌</text><text>正在准备你的购物首页…</text></view>
   <view v-else-if="error" class="m-empty"><text>商城服务暂时无法连接</text><text class="m-muted">{{error}}</text><button role="button" class="m-button" @click="load">重新连接</button></view>
   <template v-else>
    <template v-if="active==='home'">
     <view class="m-home-top"><view class="m-hero"><view class="m-hero-copy"><view class="m-hero-pill">SHOP & EARN / 购物积分计划</view><text class="m-hero-title">每一笔购物<br/>都有积分回礼</text><text class="m-hero-sub">好物买回家，积分留给下一份惊喜。</text><view class="m-hero-actions"><button role="button" @click="go('category')">去逛好物 <text>↗</text></button><text @click="rules">购物返积分规则 →</text></view><view class="m-hero-steps"><text>01 挑选好物</text><text>→</text><text>02 确认收货</text><text>→</text><text>03 积分兑礼</text></view></view><view class="m-hero-art"><image src="/static/shop-hero.svg" mode="aspectFit"/></view><text class="m-hero-stamp">GOOD FINDS.<br/>MORE REWARDS.</text></view><view class="m-member-card"><view class="m-member-top"><text>曜集会员 · 积分账户</text><text>◇</text></view><view class="m-member-balance">{{pointBalance}}<text>可用积分</text></view><text class="m-member-pending">{{user?`待入账 ${user.pendingPoints} 积分`:'登录后查看购物积分'}}</text><view class="m-member-buttons"><button role="button" @click="user?go('points'):modal='login'">{{user?'积分兑换':'登录体验'}} ↗</button><text @click="go('wallet')">查看明细 →</text></view><view class="m-member-foot"><text>每满 ¥1</text><text>返 1 积分</text><text>确认收货后到账</text></view></view></view>
     <view class="m-service-strip"><text>▣ 购物得积分</text><text>◇ 积分兑好礼</text><text>▤ 订单可追踪</text><text>✓ 规则透明可查</text></view>
     <view class="m-category-shortcuts"><view v-for="(c,i) in [{name:'数码好物',icon:'◉',tone:'peach'},{name:'生活美学',icon:'⌂',tone:'mint'},{name:'出行装备',icon:'▱',tone:'purple'},{name:'积分兑礼',icon:'◇',tone:'gold'},{name:'每日签到',icon:'✓',tone:'rose'}]" :key="i" @click="c.name==='积分兑礼'?go('points'):c.name==='每日签到'?go('tasks'):(go('category'),category=c.name)"><view :class="'m-category-icon '+c.tone">{{c.icon}}</view><text>{{c.name}}</text></view></view>
     <view class="m-feature-row"><view class="m-feature m-feature-coupon" @click="go('points')"><view><text class="m-feature-eyebrow">POINTS TO PERKS</text><text class="m-feature-title">积分换券，下单更划算</text><text class="m-feature-sub">300 积分兑换满 200 减 20 购物券</text><text class="m-feature-link">去兑换 →</text></view><view class="m-feature-ticket"><text>¥<text>20</text></text><text>满200可用</text></view></view><view class="m-feature m-feature-task" @click="go('tasks')"><view><text class="m-feature-eyebrow">A LITTLE EXTRA</text><text class="m-feature-title">日常小任务，积分加一点</text><text class="m-feature-sub">每日签到 · 激励体验 · 明细可查</text><text class="m-feature-link">去领积分 →</text></view><text class="m-feature-orb">✧</text></view></view>
    </template>

    <template v-if="['home','category','points'].includes(active)">
     <view v-if="active==='points'" class="m-points-hero"><view><text class="m-eyebrow">POINTS MALL / 积分商城</text><text class="m-page-title">把购物积累，兑成喜欢</text><text class="m-muted">积分兑换优惠券或好礼，兑换价格明确，无随机抽奖。</text></view><view class="m-points-balance" @click="go('wallet')">{{pointBalance}}<text>可用积分 · 查看明细 →</text></view></view>
     <view class="m-section-heading"><view><text class="m-section-title">{{active==='home'?'精选好物 · 购物得积分':active==='points'?'积分好礼':'全部商品'}}</text><text class="m-section-sub">{{active==='points'?'购物确认收货后，积分可用':'价格看得见，返积分也看得见'}}</text></view><text class="m-text-link" @click="active==='home'?go('category'):rules()">{{active==='home'?'查看全部 →':'积分规则 ↗'}}</text></view>
     <view class="m-filter"><view class="m-filter-categories"><view v-for="c in active==='points'?[...categories,'专属权益']:categories" :key="c" :class="{on:category===c}" @click="category=c">{{c}}</view></view><view class="m-sort"><text :class="{on:sort==='综合'}" @click="sort='综合'">综合</text><text :class="{on:sort==='价格升序'||sort==='低积分优先'}" @click="sort=active==='points'?'低积分优先':'价格升序'">{{active==='points'?'积分 ↑':'价格 ↑'}}</text><text v-if="active!=='points'" :class="{on:sort==='返积分优先'}" @click="sort='返积分优先'">返积分 ↓</text></view></view>
     <view v-if="!shown.length" class="m-empty"><text>没有找到匹配的商品</text><button role="button" class="m-button m-button-soft" @click="query='';category='全部'">查看全部商品</button></view>
     <view class="m-product-grid"><ShopProductCard v-for="p in shown" :key="p.id" :product="p" :points-mode="active==='points'" @open="active==='points'?redeemProduct(p):openProduct(p)" @add="active==='points'?redeemProduct(p):addCart(p)"/></view>
     <view v-if="active==='home'" class="m-bottom-story"><text>好物值得拥有，积分不止这一次。</text><view @click="go('points')">去积分商城，发现下一份好礼 →</view></view>
    </template>

    <template v-if="active==='cart'">
     <view class="m-section-heading"><view><text class="m-page-title">购物车<text class="m-title-count">{{cartCount}} 件</text></text><text class="m-muted">确认收货后获得购物积分，优惠券可在结算时选择。</text></view><text class="m-text-link" @click="go('category')">继续逛逛 →</text></view>
     <view v-if="!cart.length" class="m-empty m-white"><text class="m-empty-symbol">▱</text><text>购物车还是空的</text><text class="m-muted">选一件喜欢的好物，开启购物积分之旅。</text><button role="button" class="m-button" @click="go('category')">去挑选好物</button></view>
     <view v-else class="m-cart-layout"><view class="m-panel"><view class="m-cart-table-head"><text>商品信息</text><text>数量 / 小计</text></view><view v-for="p in cart" :key="p.id" class="m-cart-item"><image :src="photo(p.art)" mode="aspectFill" @click="openProduct(p)"/><view class="m-cart-item-info"><text class="m-item-title">{{p.name}}</text><text class="m-muted">单价 ¥{{money(p.price)}} · 确认收货返积分</text><text class="m-reward-label">预计返 {{Math.floor(p.price*p.quantity/100)}} 积分</text><text class="m-remove" @click="removeCart(p)">移除</text></view><view class="m-cart-item-end"><text class="m-item-price">¥{{money(p.price*p.quantity)}}</text><view class="m-stepper"><button role="button" aria-label="减少数量" :disabled="busy||p.quantity<=1" @click="changeQty(p,-1)">−</button><text>{{p.quantity}}</text><button role="button" aria-label="增加数量" :disabled="busy||p.quantity>=20||p.quantity>=p.stock" @click="changeQty(p,1)">＋</button></view></view></view></view><view class="m-summary"><text class="m-section-title">订单预估</text><view><text>商品金额</text><text>¥{{money(cartTotal)}}</text></view><view><text>运费</text><text>¥0.00</text></view><view class="m-summary-total"><text>合计</text><text>¥{{money(cartTotal)}}</text></view><view class="m-summary-reward">确认收货预计返 {{Math.floor(cartTotal/100)}} 积分</view><button role="button" class="m-button m-wide" @click="openCheckout(cart)">去结算（{{cartCount}}）</button><text class="m-summary-note">测试商城不扣款，不产生真实发货。</text></view></view>
    </template>

    <template v-if="active==='checkout'">
     <view class="m-section-heading"><view><text class="m-page-title">确认订单</text><text class="m-muted">商品、优惠、返积分，提交前一次看清楚。</text></view><text class="m-text-link" @click="go('cart')">返回购物车</text></view>
     <view class="m-checkout-layout"><view><view class="m-address-card" @click="modal='addresses'"><text class="m-address-pin">⌖</text><view v-if="selectedAddress" class="m-grow"><text class="m-item-title">{{selectedAddress.recipient}} <text class="m-muted-inline">{{selectedAddress.phone}}</text></text><text class="m-muted">{{selectedAddress.detail}}</text></view><view v-else class="m-grow"><text class="m-item-title">选择收货地址</text><text class="m-muted">当前为测试，请仅填写虚构信息</text></view><text>›</text></view><view class="m-panel"><view v-for="p in checkoutItems" :key="p.id" class="m-checkout-item"><image :src="photo(p.art)" mode="aspectFill"/><view class="m-grow"><text class="m-item-title">{{p.name}}</text><text class="m-muted">¥{{money(p.price)}} × {{p.quantity}}</text></view><text class="m-item-price">¥{{money(p.price*p.quantity)}}</text></view></view><view class="m-panel m-coupon-select"><text class="m-section-title">使用优惠券</text><view class="m-coupon-option" :class="{on:!couponId}" @click="couponId=''"><text>{{!couponId?'●':'○'}}</text><text>不使用优惠券</text></view><view v-for="c in availableCoupons" :key="c.id" class="m-coupon-option" :class="{on:couponId===c.id}" @click="couponId=c.id"><text>{{couponId===c.id?'●':'○'}}</text><text>满 ¥{{money(c.threshold)}} 减 ¥{{money(c.discount)}}</text></view><text v-if="!availableCoupons.length" class="m-muted">暂无符合使用条件的优惠券，可到积分商城兑换。</text></view></view><view class="m-summary"><text class="m-section-title">结算明细</text><view><text>商品总额</text><text>¥{{money(subtotal)}}</text></view><view><text>优惠券</text><text class="m-orange">−¥{{money(discount)}}</text></view><view><text>运费</text><text>¥0.00</text></view><view class="m-summary-total"><text>应付</text><text>¥{{money(payable)}}</text></view><view class="m-summary-reward">确认收货返 {{Math.floor(payable/100)}} 积分</view><button role="button" class="m-button m-wide" :disabled="busy" @click="submitOrder">提交订单</button><text class="m-summary-note">下一步为明确标注的测试付款，不调用真实支付。</text></view></view>
    </template>

    <template v-if="active==='orders'">
     <view class="m-section-heading"><text class="m-page-title">我的订单</text><text class="m-text-link" @click="go('category')">继续购物 →</text></view><view class="m-order-tabs"><view v-for="s in ['全部','待付款','待发货','待收货','已完成','已退款','已取消']" :key="s" :class="{on:orderFilter===s}" @click="orderFilter=s">{{s}}</view></view><view v-if="!visibleOrders.length" class="m-empty m-white"><text>还没有相关订单</text><button role="button" class="m-button" @click="go('category')">去逛逛</button></view><view v-for="o in visibleOrders" :key="o.id" class="m-order-card"><view class="m-order-top"><text>{{o.number}}<text class="m-order-date">{{date(o.created_at)}}</text></text><text class="m-order-status">{{orderStatus[o.status]}}</text></view><view v-for="p in o.items" :key="p.product_id" class="m-order-product"><image :src="photo(p.art)" mode="aspectFill"/><view class="m-grow"><text class="m-item-title">{{p.name}}</text><text class="m-muted">¥{{money(p.price)}} × {{p.quantity}}</text></view><text class="m-item-price">¥{{money(p.price*p.quantity)}}</text></view><view class="m-order-total"><text class="m-reward-label">{{o.status==='completed'?'已返':o.status==='cancelled'||o.status==='refunded'?'不保留':'待入账'}} {{o.reward}} 积分</text><text>订单金额 <text class="m-item-price">¥{{money(o.amount)}}</text></text></view><view class="m-order-actions"><text class="m-muted">测试交易 · 无真实支付/物流</text><button v-if="o.status==='pending'" role="button" class="m-button m-button-outline" :disabled="busy" @click="orderAction(o,'cancel')">取消订单</button><button v-if="o.status==='pending'" role="button" class="m-button" @click="payOrder=o;modal='pay'">测试付款</button><button v-if="o.status==='paid'" role="button" class="m-button" :disabled="busy" @click="orderAction(o,'demo-ship')">模拟发货</button><button v-if="o.status==='shipped'" role="button" class="m-button" :disabled="busy" @click="orderAction(o,'receive')">确认收货，领积分</button><button v-if="['paid','shipped','completed'].includes(o.status)" role="button" class="m-button m-button-outline" @click="payOrder=o;modal='refund'">申请测试退款</button></view></view>
    </template>

    <template v-if="active==='mine'">
     <view class="m-profile"><view class="m-profile-avatar">曜</view><view class="m-grow"><text class="m-page-title">{{user?'曜集会员':'欢迎来到曜集商城'}}</text><text class="m-muted">{{user?'购物积累，日常也有新期待':'登录后管理订单、收货地址和购物积分'}}</text></view><button role="button" class="m-button m-button-outline" @click="user?logout():modal='login'">{{user?'退出登录':'登录 / 注册'}}</button></view><view class="m-account-stats"><view @click="go('wallet')"><text>{{pointBalance}}</text><text>可用积分 →</text></view><view @click="showOrders()"><text>{{user?.pendingPoints||0}}</text><text>待入账积分 →</text></view><view @click="go('coupons')"><text>{{coupons.filter(c=>c.status==='available').length}}</text><text>可用优惠券 →</text></view><view @click="modal='favorites'"><text>{{favorites.length}}</text><text>我的收藏 →</text></view></view><view class="m-panel"><view class="m-section-heading"><text class="m-section-title">我的订单</text><text class="m-text-link" @click="showOrders()">全部订单 →</text></view><view class="m-order-shortcuts"><view v-for="(s,i) in ['待付款','待发货','待收货','已完成','已退款']" :key="s" @click="showOrders(s)"><text>{{['▤','▣','▱','✓','↶'][i]}}</text><text>{{s}}</text><text class="m-order-count">{{orders.filter(o=>orderStatus[o.status]===s).length}}</text></view></view></view><view class="m-personal-links"><view @click="logged()&&(modal='addresses')">收货地址 <text>›</text></view><view @click="go('coupons')">我的优惠券 <text>›</text></view><view @click="go('tasks')">签到与广告激励 <text>›</text></view><view @click="rules">购物积分规则 <text>›</text></view><view @click="privacy">隐私与体验说明 <text>›</text></view><view @click="admin">商家运营后台 <text>›</text></view></view>
    </template>

    <template v-if="active==='wallet'">
     <view class="m-wallet-banner"><view><text>我的购物积分</text><text class="m-wallet-number">{{pointBalance}}</text><text>另有 {{user?.pendingPoints||0}} 积分待确认收货后入账</text></view><button role="button" class="m-button" @click="go('points')">去兑换好礼 →</button></view><view class="m-section-heading"><text class="m-section-title">积分收支明细</text><text class="m-text-link" @click="rules">规则说明</text></view><view class="m-panel"><view v-if="!ledger.length" class="m-empty"><text>还没有积分记录</text><text class="m-muted">购物确认收货后即可获得积分，也可以参与签到。</text></view><view v-for="l in ledger" :key="l.id" class="m-ledger-row"><text class="m-ledger-icon">{{l.delta>0?'↙':'↗'}}</text><view class="m-grow"><text class="m-item-title">{{l.label}}</text><text class="m-muted">{{date(l.created_at)}}</text></view><text class="m-ledger-delta" :class="{positive:l.delta>0}">{{l.delta>0?'+':''}}{{l.delta}}</text></view></view>
    </template>

    <template v-if="active==='coupons'">
     <view class="m-section-heading"><text class="m-page-title">我的优惠券</text><text class="m-text-link" @click="go('points')">积分兑券 →</text></view><view v-if="!coupons.length" class="m-empty m-white"><text>还没有优惠券</text><text class="m-muted">购物积累积分后，可到积分商城兑换购物券。</text><button role="button" class="m-button" @click="go('points')">去积分商城</button></view><view class="m-coupons-grid"><view v-for="c in coupons" :key="c.id" class="m-coupon" :class="{unavailable:c.status!=='available'}"><view class="m-coupon-value">¥<text>{{c.discount/100}}</text></view><view class="m-grow"><text class="m-item-title">满 {{c.threshold/100}} 元购物券</text><text class="m-muted">有效期至 {{date(c.expires_at)}}</text><text class="m-orange">{{c.status==='available'?'可使用':c.status==='used'?'已使用':'已过期'}}</text></view><button v-if="c.status==='available'" role="button" class="m-button m-button-soft" @click="go('category')">去使用</button></view></view>
    </template>

    <template v-if="active==='tasks'">
     <view class="m-task-banner"><view><text class="m-eyebrow">DAILY REWARDS</text><text class="m-page-title">购物之外，多积一点</text><text class="m-muted">每日签到与自愿广告体验，作为购物积分的补充。</text></view><text>✳</text></view><view class="m-panel"><view class="m-section-heading"><text class="m-section-title">每日签到</text><text class="m-orange">连续 {{user?.streak||0}} 天</text></view><view class="m-sign-days"><view v-for="d in 7" :key="d"><text>第 {{d}} 天</text><text>✦</text><text>+{{d===7?100:20}}</text></view></view><button role="button" class="m-button m-wide" :disabled="busy||user?.checkedIn" :aria-disabled="busy||user?.checkedIn" @click="checkin">{{user?.checkedIn?'今日已签到':'签到领取积分'}}</button></view><view class="m-task-row"><view class="m-task-video">▷</view><view class="m-grow"><text class="m-item-title">看广告激励 <text class="m-mini-badge">内部演示</text></text><text class="m-muted">完成 8 秒演示得 30 积分 · 今日 {{user?.adCount||0}} / 5 次</text></view><button role="button" class="m-button m-button-soft" :disabled="busy||!adsEnabled||(user?.adCount||0)>=5" @click="startAd">去体验</button></view><view class="m-note">真实广告未接入。当前不会调用穿山甲或微信广告，也不产生广告收益。不提供朋友圈分享奖励。</view>
    </template>
    <AdPlacement v-for="p in placements.filter(p=>p.position===active)" :key="p.id" :name="p.name" :format="p.format" @explore="startAd"/>
    <view class="m-footer"><view><text>曜集商城</text><text>买好物 · 得积分 · 兑好礼</text></view><view><text @click="rules">积分规则</text><text @click="privacy">隐私说明</text><text @click="admin">商家后台</text></view><text>测试版 · 商品图片仅作展示 · 不产生真实交易</text></view>
   </template>
  </view>
  <view class="m-mobile-nav"><view v-for="n in nav" :key="n.id" :class="{on:active===n.id}" @click="go(n.id)"><view><text>{{n.icon}}</text><text v-if="n.id==='cart'&&cartCount" class="m-cart-badge">{{cartCount}}</text></view><text>{{n.short}}</text></view></view>

  <view v-if="modal" class="m-modal-mask" @click="close"><view class="m-modal" :class="{'m-detail-modal':modal==='product'}" @click.stop><view class="m-modal-close" role="button" aria-label="关闭弹窗" @click="close">×</view>
   <template v-if="modal==='login'"><view class="m-login-mark">曜</view><text class="m-eyebrow">WELCOME TO YAOJI</text><text class="m-modal-title">开启你的购物积分账户</text><text class="m-modal-desc">购物确认收货后，每满 1 元积 1 分。积分可兑换购物券及好礼，账户初始积分为 0。</text><view class="m-consent" @click="consent=!consent"><text class="m-check" :class="{on:consent}">{{consent?'✓':''}}</text><text>我同意本商城为测试版，不真实扣款或发货，并已阅读</text><text class="m-orange" @click.stop="privacy">隐私说明</text></view><button role="button" class="m-button m-wide" :disabled="busy" @click="login">同意并登录体验</button></template>
   <template v-else-if="modal==='product'&&selected"><image class="m-detail-image" :src="photo(selected.art)" mode="aspectFill"/><view class="m-detail-content"><view class="m-detail-price"><text>¥{{money(selected.price)}}</text><text>确认收货返 {{selected.rewardPoints}} 积分</text></view><text class="m-modal-title">{{selected.name}}</text><text class="m-modal-desc">{{selected.subtitle}}</text><view class="m-detail-spec"><view><text>服务</text><text>测试包邮 · 库存 {{selected.stock}} 件</text></view><view><text>积分</text><text>优惠后实付每满 1 元积 1 分，确认收货到账</text></view><view><text>说明</text><text>图片为示意，不代表实际商品型号或品牌授权</text></view></view><view class="m-detail-actions"><button role="button" class="m-favorite-button" @click="favorite(selected)">{{favorites.includes(selected.id)?'♥ 已收藏':'♡ 收藏'}}</button><button role="button" class="m-button m-button-soft" :disabled="busy||!selected.stock" @click="addCart(selected)">加入购物车</button><button role="button" class="m-button" :disabled="!selected.stock" @click="openCheckout([selected])">立即购买</button></view></view></template>
   <template v-else-if="modal==='redeem'&&selected"><image class="m-redeem-image" :src="photo(selected.art)" mode="aspectFit"/><text class="m-modal-title">{{selected.name}}</text><view class="m-redeem-points">{{selected.points}}<text>积分兑换</text></view><text class="m-modal-desc">{{selected.id==='coupon'?'满 200 元减 20 元，有效期 30 天。兑换后在结算页选择使用。':'确定性积分兑换。当前仅记录兑换，不真实发货。'}}</text><text class="m-note">可用积分 {{pointBalance}}，不支持现金购买积分。</text><button role="button" class="m-button m-wide" :disabled="busy" @click="redeem">确认积分兑换</button></template>
   <template v-else-if="modal==='pay'&&payOrder"><text class="m-eyebrow">TEST CHECKOUT / 不实际扣款</text><text class="m-modal-title">测试收银台</text><text class="m-pay-amount">¥{{money(payOrder.amount)}}</text><text class="m-modal-desc">这是模拟支付，不会唤起微信或支付宝，不产生真实扣款。完成后可在订单中模拟发货并确认收货。</text><view class="m-payment-method"><text>◉</text><text>内部测试支付</text><text>非真实商户支付</text></view><button role="button" class="m-button m-wide" :disabled="busy" @click="pay">确认测试付款（不扣款）</button></template>
   <template v-else-if="modal==='refund'&&payOrder"><text class="m-modal-title">确认测试退款？</text><text class="m-modal-desc">仅回滚测试订单，不退还真实资金。库存会恢复，购物返积分会回收。积分已被使用导致余额不足时，需人工售后审核。</text><button role="button" class="m-button m-wide" :disabled="busy" @click="modal='';orderAction(payOrder,'refund')">确认测试退款</button></template>
   <template v-else-if="modal==='addresses'"><text class="m-modal-title">选择收货地址</text><text class="m-modal-desc">测试环境只填写虚构信息。</text><scroll-view scroll-y class="m-modal-scroll"><view v-for="a in addresses" :key="a.id" class="m-address-option" :class="{on:addressId===a.id}" @click="addressId=a.id;modal=''"><view class="m-grow"><text class="m-item-title">{{a.recipient}} {{a.phone}}</text><text class="m-muted">{{a.detail}}</text></view><text class="m-remove" @click.stop="removeAddress(a.id)">删除</text></view><view v-if="!addresses.length" class="m-empty">还没有收货地址</view></scroll-view><button role="button" class="m-button m-wide" @click="modal='addressForm'">＋ 新增测试地址</button></template>
   <template v-else-if="modal==='addressForm'"><text class="m-modal-title">新增测试地址</text><text class="m-modal-desc">请勿填写真实个人信息。</text><view class="m-form"><text>收货人</text><input v-model="recipient" placeholder="例如：测试用户" maxlength="30"/><text>手机号码</text><input v-model="phone" placeholder="例如：13800000000" maxlength="11" type="number"/><text>详细地址</text><textarea v-model="detail" placeholder="例如：测试省测试市演示路 1 号" maxlength="200"/></view><button role="button" class="m-button m-wide" :disabled="busy" @click="saveAddress">保存地址</button></template>
   <template v-else-if="modal==='ad'"><text class="m-eyebrow">内部演示 · 非真实广告</text><view class="m-ad-scene"><text>✳</text><text>好物与灵感，都值得多看一眼</text></view><text class="m-modal-title">完整体验后领取 30 积分</text><text class="m-modal-desc">提前关闭不奖励，演示记录 10 分钟内有效。真实广告平台尚未接入。</text><button role="button" class="m-button m-wide" :disabled="seconds>0||busy" :aria-disabled="seconds>0||busy" @click="claimAd">{{seconds?`体验中 · 剩余 ${seconds} 秒`:'领取 30 演示积分'}}</button></template>
   <template v-else-if="modal==='favorites'"><text class="m-modal-title">我的收藏</text><scroll-view scroll-y class="m-modal-scroll"><view v-if="!favorites.length" class="m-empty">还没有收藏商品</view><view v-for="p in catalog.filter(p=>favorites.includes(p.id))" :key="p.id" class="m-ledger-row" @click="openProduct(p)"><text class="m-grow">{{p.name}}</text><text class="m-orange">¥{{money(p.price)}} →</text></view></scroll-view></template>
   <template v-else><text class="m-modal-title">{{infoTitle}}</text><scroll-view scroll-y class="m-modal-scroll"><text class="m-info-body">{{infoBody}}</text></scroll-view><button role="button" class="m-button m-wide" @click="close">我知道了</button></template>
  </view></view>
  <view v-if="message" class="m-toast" role="status">{{message}}</view>
 </view>
</template>
